  //   Raptor 150 → 7 Simple Kibble    (10200/7  ≈ 1457)
  //   Valid range: [1564, 1622] — using 1600 as clean midpoint
  KIBBLE_EXTRAORDINARY: 1600,
  KIBBLE_EXCEPTIONAL: 1600,
  KIBBLE_SUPERIOR: 1600,
